using System.Globalization;
using Harbor.Catalog;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.WebUtilities;

namespace Harbor.Infrastructure;

/// <summary>Listing links, generated by Razor Pages routing.</summary>
public static class Urls
{
    /// <summary>
    /// The URL of a listing page. Parameters with default values are left out, and the rest come in
    /// the order category, sort, page.
    /// </summary>
    /// <remarks>
    /// <c>page</c> is the route value Razor Pages uses for the page name, so <c>Url.Page</c> and
    /// <c>asp-route-page</c> cannot carry a query parameter of that name. It is appended with
    /// <see cref="QueryHelpers.AddQueryString(string, string, string?)"/> instead, which also keeps it
    /// last as the spec requires.
    /// </remarks>
    public static string Listing(this IUrlHelper url, string? category, Sort sort, int page = 1)
    {
        var path = url.Page("/Products/Index", new
        {
            category,
            sort = sort == Sort.Newest ? null : sort.Param(),
        })!;
        return page == 1
            ? path
            : QueryHelpers.AddQueryString(path, "page", page.ToString(CultureInfo.InvariantCulture));
    }
}
